<script setup lang="ts">
import type {ApiClient} from '@kuaixie/sdk';
import {t,formatAmount,formatDate,formatBusinessStatus} from '@kuaixie/i18n';
import {useShopOrders,shopStockStateKey} from './useShopOrders';
const props=defineProps<{client:ApiClient;admin?:boolean;storeId?:string;storeName?:string}>();
const p=useShopOrders(props.client,!!props.admin,()=>props.storeId||'');
</script>
<template><section class="shop-orders"><h3>{{t('shopOrders.title')}}<span v-if="storeName"> · {{storeName}}</span></h3><p>{{t('shopOrders.snapshotNotice')}}</p><p v-if="p.error.value" role="alert">{{p.error.value}}</p><p v-if="admin&&!storeId">{{t('shopOrders.selectStore')}}</p><template v-else><button :disabled="p.busy.value" @click="p.load()">{{t('common.retry')}}</button><p v-if="p.busy.value">{{t('account.loading')}}</p><p v-if="!p.busy.value&&!p.error.value&&!p.rows.value.length">{{t('shopOrders.empty')}}</p><article v-for="order in p.rows.value" :key="order.id"><h4>{{order.order_no||order.id}} · {{order.item_name}}</h4><p>{{formatBusinessStatus(order.status)}} · {{formatDate(order.created_at)}}</p><dl><dt>{{t('shopOrders.quantity')}}</dt><dd>{{order.quantity}}</dd><dt>{{t('shopOrders.goods')}}</dt><dd>{{formatAmount(order.goods_amount,order.currency)}}</dd><dt>{{t('shopOrders.serviceFee')}}</dt><dd>{{formatAmount(order.service_fee,order.currency)}}</dd><dt>{{t('shopOrders.stock')}}</dt><dd>{{t(shopStockStateKey(order.stock_state))}}</dd></dl><a v-if="!admin" :href="'#services/order-actions?orderId='+encodeURIComponent(order.id)">{{t('shopOrders.orderActions')}}</a></article><button v-if="p.more.value" :disabled="p.busy.value" @click="p.load(true)">{{t('account.more')}}</button></template></section></template>
<style scoped>.shop-orders{border-top:1px solid #cbd5e1;padding:18px 0;margin-top:20px}.shop-orders p{line-height:1.7}.shop-orders article{border:1px solid #e2e8f0;border-radius:9px;padding:14px;margin:12px 0}.shop-orders dl{display:grid;grid-template-columns:1fr 1fr;gap:8px}.shop-orders dd{margin:0;text-align:right}.shop-orders [role=alert]{color:#b42318}.shop-orders button{padding:9px}</style>
